def jpr\_service\_fee(prod\_value):
# progressive rates
 thresholds = [0,80,128,208,336,544,880]
 rates = [0.0990,0.0690,0.0480,0.0340,0.0240,0.0170,0.012]
 fees = 0
 for i in range(len(rates)):
 if i == len(thresholds) - 1 or prod\_value < thresholds[i+1]:
 fees += (prod\_value - thresholds[i]) \* rates[i]
 break
 else:
 fees += (thresholds[i+1] - thresholds[i]) \* rates[i] 
 return fees

